module composite_rank(input clk, input rst_n, input start, input [7:0] n, input [7:0] k, input [255:0] str_0, input [255:0] str_1, input [255:0] str_2, input [255:0] str_3, input [255:0] str_4, input [255:0] str_5, input [255:0] str_6, input [255:0] str_7, input [7:0] len_0, input [7:0] len_1, input [7:0] len_2, input [7:0] len_3, input [7:0] len_4, input [7:0] len_5, input [7:0] len_6, input [7:0] len_7, input [511:0] test_str, input [7:0] test_len, output reg [31:0] result, output reg done); reg [2:0] state; always @(posedge clk or negedge rst_n) begin if (!rst_n) begin state <= 3'd0; done <= 1'b0; result <= 32'd0; end else begin case(state) 3'd0: if (start) state <= 3'd1; 3'd1: state <= 3'd2; 3'd2: state <= 3'd3; 3'd3: state <= 3'd4; 3'd4: state <= 3'd5; 3'd5: state <= 3'd5; default: state <=3'd0; endcase end end endmodule